import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.rQcsxYkC.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"protocol/architecture.md","filePath":"protocol/architecture.md","lastUpdated":1785888355000}'),n={name:"protocol/architecture.md"};function o(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Arc Names is five contracts with clearly separated jobs, plus an indexer that turns their events into a queryable API. This page explains what each piece does and why the split exists.</p><h2 id="the-contracts" tabindex="-1">The contracts <a class="header-anchor" href="#the-contracts" aria-label="Permalink to &quot;The contracts&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>                    │              Registry (ENS)              │</span></span>
<span class="line"><span>                    │  node → owner, node → resolver           │</span></span>
<span class="line"><span>                    └───────────┬──────────────────┬───────────┘</span></span>
<span class="line"><span>                                │                  │</span></span>
<span class="line"><span>                  setSubnodeOwner│                  │resolver lookup</span></span>
<span class="line"><span>                                │                  │</span></span>
<span class="line"><span>                    ┌───────────▼──────┐   ┌───────▼──────────┐</span></span>
<span class="line"><span>                    │    Registrar     │   │     Resolver     │</span></span>
<span class="line"><span>                    │  ERC-721 + expiry│   │ addr/text/content│</span></span>
<span class="line"><span>                    └───────▲──────────┘   └──────────────────┘</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>              register/renew│ (onlyController)</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>       ┌────────────────────┴─────────┐        ┌──────────────────┐</span></span>
<span class="line"><span>       │         Controller           │        │      Market      │</span></span>
<span class="line"><span>       │ pricing, commit-reveal, pay  │        │  listings, sales │</span></span>
<span class="line"><span>       └──────────────────────────────┘        └──────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>       ┌──────────────────────────────┐        ┌──────────────────┐</span></span>
<span class="line"><span>       │      UniversalResolver       │        │ ReverseRegistrar │</span></span>
<span class="line"><span>       │ forward + verified reverse   │        │  address → node  │</span></span>
<span class="line"><span>       └──────────────────────────────┘        └──────────────────┘</span></span></code></pre></div><h3 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h3><p>The root of the system. It stores two mappings per node: who owns it, and which resolver answers for it. It knows nothing about prices, expiry, or NFTs.</p><p>Every resolution starts here. Every record write is authorised against the ownership recorded here — which is why <a href="/docs/guide/ownership.html#reclaiming-after-a-transfer">reclaim</a> matters after a transfer.</p><h3 id="registrar" tabindex="-1">Registrar <a class="header-anchor" href="#registrar" aria-label="Permalink to &quot;Registrar&quot;">​</a></h3><p>Owns the <code>.arc</code> node in the registry, and issues names beneath it. It is the ERC-721 contract: it holds the token, the expiry, and the label for each name.</p><p>Two access-control notes:</p><ul><li><code>register</code> and <code>renew</code> are <code>onlyController</code> — no user calls them directly. Ordinary users reach them through the controller, which handles payment.</li><li>A <code>live</code> modifier requires that the registrar still owns the <code>.arc</code> node in the registry. If that ever stops being true, registration and renewal halt with <code>!live</code> rather than silently writing to a node the registrar no longer controls.</li></ul><p><code>GRACE</code> is a hard constant here — 90 days, not configurable.</p><h3 id="controller" tabindex="-1">Controller <a class="header-anchor" href="#controller" aria-label="Permalink to &quot;Controller&quot;">​</a></h3><p>The public entry point for getting a name. It owns:</p><ul><li><strong>Pricing</strong> — the four length tiers and the per-second proration.</li><li><strong>Commit-reveal</strong> — <code>commit</code>, <code>minCommitAge</code>/<code>maxCommitAge</code>, and the anti-front-running logic.</li><li><strong>Payment</strong> — native and ERC-20 USDC paths, refunds, referral discounts and rewards.</li><li><strong>Validation</strong> — <code>valid()</code>, <code>minLen</code>, the 2-character tier switch.</li></ul><p>It is a registrar controller, meaning it is on the registrar&#39;s allowlist. This is the piece most likely to be replaced over time: pricing models and payment methods change, and swapping the controller doesn&#39;t touch names, records or ownership.</p><h3 id="resolver" tabindex="-1">Resolver <a class="header-anchor" href="#resolver" aria-label="Permalink to &quot;Resolver&quot;">​</a></h3><p>Stores the actual records — address, text, contenthash, and the reverse <code>name</code> — keyed by node. Writes are gated by <code>auth</code>, which checks registry ownership.</p><p>Resolvers are pluggable: the registry points each name at one, so a name can move to a custom resolver with different behaviour. Records do not follow — they live in whichever resolver holds them, which is why <a href="/docs/guide/records.html#binding-a-resolver">writing to an unbound resolver</a> is a silent mistake.</p><h3 id="market" tabindex="-1">Market <a class="header-anchor" href="#market" aria-label="Permalink to &quot;Market&quot;">​</a></h3><p>Escrow-free listings. The seller approves the market and lists; the market transfers on sale using that approval. The name never leaves the seller&#39;s wallet until it sells.</p><p>It has its own fee (<code>feeBps</code>) and its own referral system, both independent of the controller&#39;s.</p><h3 id="universalresolver-and-reverseregistrar" tabindex="-1">UniversalResolver and ReverseRegistrar <a class="header-anchor" href="#universalresolver-and-reverseregistrar" aria-label="Permalink to &quot;UniversalResolver and ReverseRegistrar&quot;">​</a></h3><p>Convenience contracts for resolution. The reverse registrar derives the reverse node for an address; the universal resolver does the full forward lookup and the <strong>verified</strong> reverse lookup in one call. See <a href="/docs/protocol/resolving.html">Resolving .arc</a>.</p><h2 id="why-the-split" tabindex="-1">Why the split <a class="header-anchor" href="#why-the-split" aria-label="Permalink to &quot;Why the split&quot;">​</a></h2><p>It would be simpler to put all of this in one contract. The separation buys three things:</p><p><strong>Upgradeability without migration.</strong> Pricing lives in the controller. Change pricing and no name, record or ownership entry moves. Swap the controller entirely and existing names are untouched.</p><p><strong>Independent record storage.</strong> Because records live in a pluggable resolver rather than beside ownership, a name can point at a resolver with entirely different behaviour without the registry knowing or caring.</p><p><strong>Minimal trusted core.</strong> The registry is small and rarely changes. The contracts that do change — controller, market — hold no user data. A bug in the market cannot affect who owns a name.</p><h2 id="proxies-and-upgradeability" tabindex="-1">Proxies and upgradeability <a class="header-anchor" href="#proxies-and-upgradeability" aria-label="Permalink to &quot;Proxies and upgradeability&quot;">​</a></h2><p>Every contract is deployed behind an <strong>ERC-1967 proxy</strong> using the UUPS pattern. The addresses in <a href="/docs/protocol/contracts.html">Contract addresses</a> are all proxies.</p><div class="warning custom-block"><p class="custom-block-title">Call the proxy, never the implementation</p><p>All state lives in the proxy. Calling an implementation address directly reads uninitialised storage and returns nonsense — it will not revert, it will return zeros. Always use the proxy addresses.</p></div><p>Upgrades are authorised by the contract owner via <code>_authorizeUpgrade</code>. Ownership uses a two-step transfer (<code>transferOwnership</code> → <code>acceptOwnership</code>), which prevents handing ownership to an address that can&#39;t accept it.</p><div class="danger custom-block"><p class="custom-block-title">This is a trust assumption</p><p>The contract owner can upgrade any contract, change prices, adjust <code>minLen</code> and commit ages, alter fees, and enable or disable referrals. An upgrade could change any behaviour described in these docs.</p><p>That is normal for a young protocol and is what allows fixing bugs, but it is a real trust assumption you should weigh. See <a href="/docs/safety.html#trust-assumptions">Safety</a>.</p></div><h2 id="owner-controlled-parameters" tabindex="-1">Owner-controlled parameters <a class="header-anchor" href="#owner-controlled-parameters" aria-label="Permalink to &quot;Owner-controlled parameters&quot;">​</a></h2><p>None of these are constants. All are live on-chain values, readable from the contracts:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Contract</th><th>Controls</th></tr></thead><tbody><tr><td><code>price2</code>, <code>price3</code>, <code>price4</code>, <code>price5plus</code></td><td>Controller</td><td>Per-year rates by length</td></tr><tr><td><code>minLen</code></td><td>Controller</td><td>Shortest registerable name (never below 2)</td></tr><tr><td><code>minCommitAge</code>, <code>maxCommitAge</code></td><td>Controller</td><td>The commit-reveal window</td></tr><tr><td><code>refDiscountBps</code>, <code>refRewardBps</code></td><td>Controller</td><td>Registration referrals (each ≤ 2000)</td></tr><tr><td><code>feeBps</code>, <code>feeRecipient</code></td><td>Market</td><td>Marketplace fee</td></tr><tr><td><code>refDiscountBps</code>, <code>refRewardBps</code></td><td>Market</td><td>Sale referrals (sum ≤ <code>feeBps</code>)</td></tr><tr><td><code>usdc</code></td><td>Both</td><td>ERC-20 USDC address; zero disables that path</td></tr></tbody></table><p>What <strong>is</strong> fixed in code:</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th></tr></thead><tbody><tr><td><code>GRACE</code></td><td>90 days</td></tr><tr><td><code>MIN_DURATION</code></td><td>28 days</td></tr><tr><td><code>MAX_DURATION</code></td><td>36,500 days (100 years)</td></tr><tr><td>Pricing denominator</td><td>365 days</td></tr></tbody></table><h2 id="the-indexer" tabindex="-1">The indexer <a class="header-anchor" href="#the-indexer" aria-label="Permalink to &quot;The indexer&quot;">​</a></h2><p>The contracts are the source of truth, but they can&#39;t answer &quot;every name owned by this address&quot; or &quot;the last 25 sales&quot; — that requires scanning logs.</p><p>The indexer subscribes to events from the registrar, controller and market, writes them to a database, and serves <a href="/docs/api/endpoints.html">a REST API</a>. It tracks each contract as a separate <strong>stream</strong> with its own checkpoint, and reports the <em>minimum</em> across streams as its indexed block — so it never claims to be fresher than its slowest stream.</p><div class="info custom-block"><p class="custom-block-title">The API is a convenience, not an authority</p><p>The indexer lags the chain and can fall behind or fail. For display, that&#39;s fine. For anything that moves value, read the contracts. Check <code>GET /api/v1/sync-status</code> to know how far behind it is.</p></div><h2 id="transaction-flows-end-to-end" tabindex="-1">Transaction flows end to end <a class="header-anchor" href="#transaction-flows-end-to-end" aria-label="Permalink to &quot;Transaction flows end to end&quot;">​</a></h2><p><strong>Registration:</strong> <code>commit</code> → wait <code>minCommitAge</code> → <code>register</code> → controller validates, prices, and calls registrar <code>register</code> → binds resolver, sets <code>addr</code>, <code>reclaim</code>, transfers token to you.</p><p><strong>Renewal:</strong> <code>renew</code> → controller prices → registrar extends the expiry. One transaction, no commit needed.</p><p><strong>Sale:</strong> seller <code>approve</code> + <code>list</code> → buyer <code>buy</code> → market checks price and ownership, transfers token, pays the seller minus fee.</p><p><strong>Record write:</strong> <code>setAddr</code>/<code>setText</code> on the resolver → <code>auth</code> checks registry ownership → stores and emits.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/protocol/contracts.html">Contract addresses</a> — the deployed addresses.</li><li><a href="/docs/protocol/resolving.html">Resolving .arc</a> — the resolution algorithm.</li><li><a href="/docs/protocol/fees.html">Fees</a> — where money goes.</li></ul>`,50)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
